/** Entity of the "order_lines" table. */
import { Column, Entity, JoinColumn, ManyToOne, PrimaryColumn, type Relation } from 'typeorm'
import { Order } from './order.js'
import { Product } from './product.js'

/** A row of the "order_lines" table. */
@Entity({ name: 'order_lines' })
export class OrderLine {
  @PrimaryColumn({ name: 'order_id', type: 'bigint' })
  orderId!: number

  @PrimaryColumn({ type: 'integer' })
  line!: number

  @Column({ name: 'product_id', type: 'bigint' })
  productId!: number

  @Column({ type: 'integer' })
  quantity!: number

  /** The Order this row points to (order_id); loaded only when asked for */
  @ManyToOne(() => Order, { nullable: false, onDelete: 'CASCADE' })
  @JoinColumn({ name: 'order_id', referencedColumnName: 'id' })
  order?: Relation<Order>

  /** The Product this row points to (product_id); loaded only when asked for */
  @ManyToOne(() => Product, { nullable: false, onDelete: 'RESTRICT' })
  @JoinColumn({ name: 'product_id', referencedColumnName: 'id' })
  product?: Relation<Product>
}

