/** Entity of the "products" table. */
import { Check, Column, Entity, Index, JoinColumn, ManyToOne, PrimaryGeneratedColumn, type Relation } from 'typeorm'
import { decimalText } from '../column-types.js'
import { Category } from './category.js'

/** A row of the "products" table. */
@Entity({ name: 'products' })
@Index('ix_products_status', ['status'])
@Index(['categoryId'])
@Check('price >= 0')
export class Product {
  @PrimaryGeneratedColumn({ type: 'bigint' })
  id!: number

  @Column({ name: 'category_id', type: 'bigint' })
  categoryId!: number

  @Column({ type: 'varchar', length: 100 })
  name!: string

  @Column({ type: 'numeric', precision: 10, scale: 2, transformer: decimalText })
  price!: string

  @Column({ type: 'varchar', length: 10 })
  status!: string

  @Column({ type: 'integer', default: 1 })
  version!: number

  @Column({ name: 'deleted_at', type: 'timestamptz', nullable: true })
  deletedAt!: Date | null

  /** The Category this row points to (category_id); loaded only when asked for */
  @ManyToOne(() => Category, { nullable: false })
  @JoinColumn({ name: 'category_id', referencedColumnName: 'id', foreignKeyConstraintName: 'fk_products_category' })
  category?: Relation<Category>
}

