/** Repository of the "audit_log" table: reads and writes rows, and decides nothing. */
import type { EntityManager } from 'typeorm'
import { AuditLog } from '../entities/audit-log.js'
import type { Page } from '../paging.js'

/** Keeps audit_log rows in the database, through an EntityManager. Every write is committed at once. */
export class SqlAuditLogRepository {
  constructor(private readonly manager: EntityManager) {}

  /** At most `limit` rows from `offset`, by primary key, and how many there are. */
  async list(offset: number = 0, limit: number = 50): Promise<Page<AuditLog>> {
    const [items, total] = await this.manager.findAndCount(AuditLog, { order: { at: 'ASC', message: 'ASC' }, skip: offset, take: limit })
    return { items, total, offset, limit }
  }
}

