/** Repository of the "categories" table: reads and writes rows, and decides nothing. */
import { QueryFailedError, type EntityManager } from 'typeorm'
import { Category } from '../entities/category.js'
import { ConflictError } from '../errors.js'
import type { Page } from '../paging.js'

/** Keeps categories rows in the database, through an EntityManager. Every write is committed at once. */
export class SqlCategoryRepository {
  constructor(private readonly manager: EntityManager) {}

  /** The row with this primary key, or null. */
  async getById(id: number): Promise<Category | null> {
