import { Product } from '../entities/product.js'
import { ProductTag } from '../entities/product-tag.js'
import { ConflictError, NotFoundError, ValidationFailedError, type FieldError } from '../errors.js'
import type { Page } from '../paging.js'
import type { UnitOfWork } from '../unit-of-work.js'

/** Properties a client may send: the database fills the others */
const FIELDS = new Set(['categoryId', 'name', 'price', 'status', 'version', 'deletedAt'])

/** Operations on products. Repositories commit every write. */
export class ProductService {
  constructor(private readonly uow: UnitOfWork) {}

  /** Checks the values against the rules of the "products" table, and the rows they point to; throws ValidationFailedError with every problem. */
  private async validate(uow: UnitOfWork, values: Partial<Record<string, unknown>>, current: Product | null): Promise<void> {
    const creating = current === null
    const errors: FieldError[] = []
    for (const name of Object.keys(values)) if (!FIELDS.has(name)) errors.push({ field: name, message: 'is not a field of Product' })
    if (!creating) for (const name of Object.keys(values)) if (['id', 'version', 'deletedAt'].includes(name)) errors.push({ field: name, message: 'cannot be changed' })
    {
      const value = values.categoryId
      if (value == null) {
        if (creating || 'categoryId' in values) errors.push({ field: 'category_id', message: 'is required' })
      }
    }
    {
      const value = values.name
      if (value == null) {
        if (creating || 'name' in values) errors.push({ field: 'name', message: 'is required' })
      } else {
        if (typeof value === 'string' && value.length > 100) errors.push({ field: 'name', message: 'is longer than 100 characters' })
      }
    }
    {
      const value = values.price
      if (value == null) {
        if (creating || 'price' in values) errors.push({ field: 'price', message: 'is required' })
      } else {
        if (!(Number(value) >= 0)) errors.push({ field: 'price', message: 'must be >= 0' })
      }
    }
    {
      const value = values.status
      if (value == null) {
        if (creating || 'status' in values) errors.push({ field: 'status', message: 'is required' })
      } else {
        if (typeof value === 'string' && value.length > 10) errors.push({ field: 'status', message: 'is longer than 10 characters' })
      }
    }
    {
      const value = values.version
      if (value == null) {
        if ('version' in values && !creating) errors.push({ field: 'version', message: 'cannot be empty' })
      }
    }
    {
      const categoryId = 'categoryId' in values ? values.categoryId : current?.categoryId
      if (categoryId != null && (await uow.categories.getById(categoryId as number)) === null)
        errors.push({ field: 'category_id', message: 'no Category has this key' })
    }
    if (errors.length > 0) throw new ValidationFailedError('Product', errors)
  }

  /** Every check before a write: the values, the rows they point to, the unique values. */
  private async check(uow: UnitOfWork, values: Partial<Record<string, unknown>>, current: Product | null): Promise<void> {
    await this.validate(uow, values, current)
  }

  /** The Product with this key; NotFoundError when there is none. */
  private async find(uow: UnitOfWork, id: number): Promise<Product> {
    const entity = await uow.products.getById(id)
    if (entity === null) throw new NotFoundError('Product', id)
    return entity
  }

  /** Stores a new Product after checking it. */
  async createProduct(product: Product): Promise<Product> {
    const values: Partial<Record<string, unknown>> = Object.fromEntries([...FIELDS].map((field) => [field, (product as unknown as Record<string, unknown>)[field]]))
    return this.uow.transaction(async (uow) => {
      await this.check(uow, values, null)
      const created = await uow.products.insert(product)
      return created
    })
  }

  /** The Product with this key; NotFoundError when there is none. */
  async getProduct(id: number): Promise<Product> {
    return await this.find(this.uow, id)
  }

  /** A page of products, by primary key. */
  async listProducts(offset = 0, limit = 50): Promise<Page<Product>> {
    return this.uow.products.list(offset, limit)
  }

  /** Changes the given values of a Product, read at `version`. */
  async updateProduct(id: number, changes: Partial<Product>, version: number): Promise<Product> {
    const values: Partial<Record<string, unknown>> = Object.fromEntries(Object.entries(changes).filter(([, value]) => value !== undefined))
    return this.uow.transaction(async (uow) => {
      const current = await this.find(uow, id)
      if (current.version !== version)
        throw new ConflictError('Product', 'was changed by someone else since it was read', ['version'])
      await this.check(uow, values, current)
      Object.assign(current, values)
      current.version = version + 1
      const updated = await uow.products.update(current)
      return updated
    })
  }

  /** Marks a Product as deleted (deleted_at); reads leave it out from then on. */
  async deleteProduct(id: number, version: number): Promise<void> {
    return this.uow.transaction(async (uow) => {
      const current = await this.find(uow, id)
      if (current.version !== version)
        throw new ConflictError('Product', 'was changed by someone else since it was read', ['version'])
      if ((await uow.orderLines.listByProductId(current.id)).length > 0) throw new ConflictError('Product', 'rows of order_lines still point to it', ['order_lines'])
      current.deletedAt = new Date()
      await uow.products.update(current)
    })
  }

  /** The products with this category_id. */
  async listProductsByCategoryId(categoryId: number): Promise<Product[]> {
    return await this.uow.products.listByCategoryId(categoryId)
  }

  /** Links a Product and a Tag (product_tags). */
  async addTag(productId: number, tagId: number): Promise<void> {
    return this.uow.transaction(async (uow) => {
      await this.find(uow, productId)
      if ((await uow.tags.getById(tagId)) === null) throw new NotFoundError('Tag', tagId)
      if (await uow.productTags.getByProductIdAndTagId(productId, tagId) !== null) throw new ConflictError('Product', 'is already linked to this Tag', ['tagId'])
      await uow.productTags.insert(Object.assign(new ProductTag(), { productId, tagId }))
    })
  }

  /** Removes the link between a Product and a Tag (product_tags). */
  async removeTag(productId: number, tagId: number): Promise<void> {
    return this.uow.transaction(async (uow) => {
      const link = await uow.productTags.getByProductIdAndTagId(productId, tagId)
      if (link === null) throw new NotFoundError('ProductTag', [productId, tagId])
      await uow.productTags.delete(link)
    })
  }
}

