/** Tests of the "categories" table. */
import { describe, expect, it } from 'vitest'
import { ConflictError, NotFoundError, ValidationFailedError } from '../src/errors.js'
import { CategoryService } from '../src/services/category.js'
import { useTestDatabase } from './database.js'
import { addCategory, newCategory } from './factories.js'

/** The repositories over the test database, opened empty for every test */
const sqlUow = useTestDatabase()

describe('categories repository', () => {
  it('is stored and read back', async () => {
    const uow = sqlUow()
    const stored = await addCategory(uow, 1)
    const found = await uow.categories.getById(stored.id)
    expect(found).not.toBeNull()
    expect(found!.id).toEqual(stored.id)
    expect(await uow.categories.getByName(stored.name)).not.toBeNull()
  })

  it('lists rows by key', async () => {
    const uow = sqlUow()
    await addCategory(uow, 1)
    await addCategory(uow, 2)
    const page = await uow.categories.list(0, 1)
    expect(page.total).toBe(2)
    expect(page.items).toHaveLength(1)
  })

  it('is deleted', async () => {
    const uow = sqlUow()
    const stored = await addCategory(uow, 1)
    await uow.categories.delete(stored)
    expect(await uow.categories.getById(stored.id)).toBeNull()
  })
})

describe('CategoryService', () => {
  it('creates a valid row', async () => {
    const uow = sqlUow()
    const service = new CategoryService(uow)
    const n = 1
    const created = await service.createCategory(newCategory(1))
    const found = await service.getCategory(created.id)
    expect(found.id).toEqual(created.id)
  })

  it('refuses a missing value', async () => {
    const uow = sqlUow()
    const service = new CategoryService(uow)
    const n = 1
    const error: unknown = await service.createCategory(newCategory(1, { name: null as never })).catch((caught: unknown) => caught)
    expect(error).toBeInstanceOf(ValidationFailedError)
    expect((error as ValidationFailedError).errors.map((item) => item.field)).toEqual(['name'])
  })

  it('refuses a repeated unique value', async () => {
    const uow = sqlUow()
    const service = new CategoryService(uow)
    const n = 1
    const first = await service.createCategory(newCategory(1))
    await expect(service.createCategory(newCategory(2, { name: first.name }))).rejects.toBeInstanceOf(ConflictError)
  })

  it('keeps its own unique value', async () => {
    const uow = sqlUow()
    const service = new CategoryService(uow)
    const n = 1
    const created = await service.createCategory(newCategory(1))
    await service.updateCategory(created.id, { name: created.name })
  })

  it('says when a row is missing', async () => {
    const uow = sqlUow()
    const service = new CategoryService(uow)
    await expect(service.getCategory(999999)).rejects.toBeInstanceOf(NotFoundError)
  })

  it('deletes a row', async () => {
    const uow = sqlUow()
    const service = new CategoryService(uow)
    const n = 1
    const created = await service.createCategory(newCategory(1))
    await service.deleteCategory(created.id)
    await expect(service.getCategory(created.id)).rejects.toBeInstanceOf(NotFoundError)
  })
})

