import type { UnitOfWork } from '../src/unit-of-work.js'

/** A valid Customer that is not stored yet; `n` makes its unique values differ, `values` replace any of them. */
export function newCustomer(n = 1, values: Partial<Customer> = {}): Customer {
  return Object.assign(new Customer(), { email: `email-${n}`, passwordHash: `passwordhash-${n}` }, values)
}

/** A stored Customer. */
export async function addCustomer(uow: UnitOfWork, n = 1): Promise<Customer> {
  return uow.customers.insert(newCustomer(n))
}

/** A valid Category that is not stored yet; `n` makes its unique values differ, `values` replace any of them. */
export function newCategory(n = 1, values: Partial<Category> = {}): Category {
  return Object.assign(new Category(), { name: `name-${n}` }, values)
}

/** A stored Category. */
export async function addCategory(uow: UnitOfWork, n = 1): Promise<Category> {
  return uow.categories.insert(newCategory(n))
}

/** A valid Product that is not stored yet; `n` makes its unique values differ, `values` replace any of them. */
export function newProduct(n = 1, values: Partial<Product> = {}): Product {
  return Object.assign(new Product(), { name: `name-${n}`, price: `${n % 10000}.50`, status: `status-${n}`, version: n, deletedAt: null }, values)
}

/** A stored Product, with the rows it points to. */
export async function addProduct(uow: UnitOfWork, n = 1): Promise<Product> {
  const parent0 = await addCategory(uow, n)
  return uow.products.insert(newProduct(n, { categoryId: parent0.id }))
}

